{%- set v_extras = (p.extras ?? null) -%}
{%- if og_t(og_gt(og_len(og_get(v_extras, ['channels'])), 0)) %}
  {%- set c_5 -%}
    {%- for v_c in og_l(og_get(v_extras, ['channels'])) %}
