          {%- endset -%}
          {{ include('compose/Inline.html.twig', {'class': 'flex size-10 shrink-0 items-center justify-center rounded bg-muted text-foreground', 'children': c_1}, with_context = false) }}
          {%- set c_2 -%}
            {{ og_text(og_get(v_c, ['title'])) }}
          {%- endset -%}
          {{ include('compose/Text.html.twig', {'size': 'sm', 'weight': 'semibold', 'children': c_2}, with_context = false) }}
          {%- set c_3 -%}
            {{ og_text(og_get(v_c, ['text'])) }}
          {%- endset -%}
          {{ include('compose/Text.html.twig', {'size': 'xs', 'class': 'text-muted-foreground', 'children': c_3}, with_context = false) }}
        {%- endset -%}
        {{ include('compose/Stack.html.twig', {'gap': '2', 'align': 'start', 'class': 'rounded bg-card inset-ring inset-ring-border p-4', 'attrs': og_attrs(['data-testid', 'footer-channel']), 'children': c_4}, with_context = false) }}
      {%- endif %}
    {%- endfor %}
  {%- endset -%}
  {{ include('compose/Box.html.twig', {'class': 'grid grid-cols-1 gap-4 sm:grid-cols-3', 'children': c_5}, with_context = false) }}
{%- endif %}
